#!/usr/bin/env python3
import csv
import json
import os

from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)
PENALTY = float(cfg.get("shortfall_penalty_per_m3", 18.0))
TOL = float(cfg.get("feasibility_tolerance", 1e-5))

sources = {}
with open(os.path.join(DATA, "reuse_sources.csv")) as f:
    for row in csv.DictReader(f):
        s = row["source_id"].strip()
        sources[s] = {
            "avail": float(row["available_m3"]),
            "cost": float(row["base_cost_per_m3"]),
            "tds": float(row["tds_mg_l"]),
            "nitrogen": float(row["nitrogen_mg_l"]),
            "hardness": float(row["hardness_mg_l"]),
        }

users = {}
with open(os.path.join(DATA, "water_users.csv")) as f:
    for row in csv.DictReader(f):
        u = row["user_id"].strip()
        users[u] = {
            "demand": float(row["demand_m3"]),
            "rate": float(row["minimum_service_rate"]),
            "tds": float(row["max_tds_mg_l"]),
            "nitrogen": float(row["max_nitrogen_mg_l"]),
            "hardness": float(row["max_hardness_mg_l"]),
        }

lanes = []
lane_info = {}
with open(os.path.join(DATA, "source_user_lanes.csv")) as f:
    for row in csv.DictReader(f):
        s = row["source_id"].strip()
        u = row["user_id"].strip()
        cap = float(row["lane_capacity_m3"])
        tc = float(row["transfer_cost_per_m3"])
        lanes.append((s, u))
        lane_info[(s, u)] = {"cap": cap, "tc": tc}

# ---------------- Build model ----------------
model = Model("water_reuse_blending")
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

f = {}
obj_coeff = {}
for (s, u) in lanes:
    c = sources[s]["cost"] + lane_info[(s, u)]["tc"]
    obj_coeff[(s, u)] = c
    f[(s, u)] = model.addVar(name=f"f_{s}_{u}", vtype="C", lb=0.0,
                             ub=lane_info[(s, u)]["cap"], obj=c)

sh = {}
for u in users:
    sh[u] = model.addVar(name=f"sh_{u}", vtype="C", lb=0.0,
                         ub=users[u]["demand"] * (1.0 - users[u]["rate"]),
                         obj=PENALTY)

obj_expr = quicksum([obj_coeff[(s, u)] * f[(s, u)] for (s, u) in lanes])
obj_expr += quicksum([PENALTY * sh[u] for u in users])
model.setObjective(obj_expr, sense="minimize")

# Source availability
for s in sources:
    model.addCons(
        quicksum([f[(s, u)] for (s2, u) in lanes if s2 == s]) <= sources[s]["avail"],
        name=f"avail_{s}",
    )

# Demand balance + min service + quality per user
for u in users:
    inflow = quicksum([f[(s, u)] for (s, u) in lanes])
    model.addCons(inflow + sh[u] == users[u]["demand"], name=f"bal_{u}")
    model.addCons(inflow >= users[u]["rate"] * users[u]["demand"], name=f"minsvc_{u}")
    for attr in ("tds", "nitrogen", "hardness"):
        model.addCons(
            quicksum([(sources[s][attr] - users[u][attr]) * f[(s, u)]
                      for (s, u) in lanes]) <= 0.0,
            name=f"qual_{u}_{attr}",
        )

# ---------------- Solve ----------------
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    if model.getNSols() > 0:
        objval = model.getObjVal()
    print("Solver status:", status)
    print("Objective:", objval)
except Exception as e:
    print("Solver error:", e)
    status = "error"

# ---------------- Extract solution ----------------
fval = {}
shval = {}
if model.getNSols() > 0:
    for (s, u) in lanes:
        fval[(s, u)] = max(0.0, model.getVal(f[(s, u)]))
    for u in users:
        shval[u] = max(0.0, model.getVal(sh[u]))
else:
    for (s, u) in lanes:
        fval[(s, u)] = 0.0
    for u in users:
        shval[u] = 0.0

# ---------------- Validation ----------------
print("Validation checks:")
ok = True
for s in sources:
    tot = sum(fval[(s, u)] for (s2, u) in lanes if s2 == s)
    if tot > sources[s]["avail"] + TOL:
        ok = False
        print(f"  FAIL source avail {s}: {tot} > {sources[s]['avail']}")
for (s, u) in lanes:
    if fval[(s, u)] > lane_info[(s, u)]["cap"] + TOL:
        ok = False
        print(f"  FAIL lane cap {s}->{u}: {fval[(s, u)]}")
for u in users:
    inflow = sum(fval[(s, u)] for (s, u) in lanes)
    if abs(inflow + shval[u] - users[u]["demand"]) > TOL:
        ok = False
        print(f"  FAIL balance {u}: {inflow + shval[u]} vs {users[u]['demand']}")
    if inflow < users[u]["rate"] * users[u]["demand"] - TOL:
        ok = False
        print(f"  FAIL min service {u}: {inflow}")
    for attr in ("tds", "nitrogen", "hardness"):
        lhs = sum((sources[s][attr] - users[u][attr]) * fval[(s, u)]
                  for (s, u) in lanes)
        if lhs > TOL:
            ok = False
            print(f"  FAIL quality {u} {attr}: {lhs}")
print("  All checks passed" if ok else "  SOME CHECKS FAILED")

# ---------------- Write solution ----------------
sol_path = os.path.join(SUB, "solution.csv")
with open(sol_path, "w", newline="") as fp:
    w = csv.writer(fp)
    w.writerow(["row_type", "source_id", "user_id", "value"])
    for (s, u) in lanes:
        w.writerow(["flow", s, u, f"{fval[(s, u)]:.8f}"])
    for u in users:
        w.writerow(["shortfall", "", u, f"{shval[u]:.8f}"])
print("Wrote", sol_path)

model.free()
